  v = `Tùy chọn: Bạn có thể mời các nhà phát triển khác để đưa trò chơi của họ vào bộ sản phẩm của mình. Với tư cách chủ sở hữu, bạn sẽ chịu trách nhiệm phối hợp với các nhà phát triển khác. Đồng thời, bạn cũng người duy nhất có thể phát hành bộ sản phẩm trên cửa hàng Steam. Các bên được mời sẽ có thể chọn trò chơi/gói nào để thêm vào. Bất cứ khi nào một gói được thêm vào bộ sản phẩm hoặc phần trăm ưu đãi thay đổi, các bên đóng góp phải chấp thuận việc đưa trò chơi của họ vào bộ trước khi nó có thể phát hành.`,
