  w = `Tổng quan trang ưu đãi`,
  T = `Trang sự kiện quảng bá ưu đãi`,
  E = `Tại đây bạn sẽ thấy các trang ưu đãi trên Steam hiển thị một hoặc nhiều trò chơi mà bạn có quyền quản lý. Trong vài trường hợp, các trang này được sắp xếp bởi người quản lý sự kiện và đôi khi, bởi chính Valve với tư cách là một phần của sự kiện giảm giá được tổ chức.`,
  D = `Đây là tất cả các trang ưu đãi đã dàn trước và hoạt động được tạo bởi Valve hoặc một đối tác ngoài có thẩm quyền. Để cài đặt một đối tác mới có thể tạo trang ưu đãi %1$s của riêng họ, bạn có thể gửi trang %2$s cho đối tác của bạn.`,
