  K = `Sự kiện này bị ẩn và bạn không có quyền chỉnh sửa. Nhưng ai đó trong nhóm của bạn thì có. Để xác định người trong nhóm có quyền chỉnh sửa sự kiện, hãy di chuột qua biểu tượng nhóm bên dưới và nhấp vào 'Xem danh sách thành viên'. Theo mặc định, thành viên có trạng thái 'ủy viên' trong nhóm có quyền chỉnh sửa đối với sự kiện này.`,
