  pt = `Trang chủ nhà sáng tạo cần tham gia bản beta Sự kiện đối tác để dùng tính năng ưu đãi. Hành động không thể được hoàn tác. Nó sẽ thay đổi công cụ chỉnh sửa họ dùng để đăng thông báo và ngăn họ tạo thông báo được liên kết. %1$s`,
