  Mm = `Một vài ứng dụng của bạn thiếu phân loại theo độ tuổi tại Đức. Bắt đầu từ 15/11/2024, Steam sẽ ngừng hiển thị các sản phẩm đó tới khách hàng tại Đức khi họ duyệt trang cửa hàng Steam. Để đảm bảo có thể bán trò chơi ở Đức, vui lòng hoàn thành và đăng tải bảng câu hỏi nội dung được tích hợp trên Steam.`,
