  Bm = `Hiện không có người dùng nào được thiết lập để nhận liên lạc từ Steamworks. Vui lòng trao quyền "Chấp nhận liên lạc từ Steamworks" cho một hoặc nhiều người dùng với địa chỉ email hợp lệ để Steam có thể thông báo tới họ về các ưu đãi và sự kiện sắp tới, tính năng mới, hoặc những lời mời đặc biệt.`,
