  Xm = `Địa chỉ này có thể khác với địa chỉ bạn cung cấp khi đăng ký Steamworks. Nếu bạn có nhiều địa điểm trong một tài khoản Steamworks, xin vui lòng nhập từng địa chỉ riêng rẽ tại đây.`,
