  lC = `Giá cơ sở của gói này trong một hay nhiều loại tiền tệ nằm dưới mức tối thiểu cho phép. Do đó, bạn không thể nhập giảm giá.`,
  uC = `Các gói sản phẩm có đánh dấu bằng biểu tượng này đang được thêm vào chương trình giảm giá đang diễn ra. Mức giảm giá được nhập sẽ lập tức có hiệu lực ngay sau khi lưu.`,
  dC = `Ưu đãi đã lên lịch này sẽ khiến giá của gói sản phẩm thấp hơn giá tối thiểu yêu cầu thuộc một hay nhiều loại tiền tệ. Vì vậy, người dùng sẽ không thể mua gói này ở các quốc gia đó. Để đảm bảo có thể mua ở mọi nơi, bạn nên nhập phần trăm ưu đãi thấp hơn %1$s% cho gói này.`,
  fC = `Giá cơ sở của gói này trong một hay nhiều loại tiền tệ thấp hơn mức tối thiểu cho phép. Vì vậy, người dùng sẽ không thể mua gói này ở các quốc gia đó hoặc ở bất kỳ nơi nào mà ưu đãi khiến giá bán nằm dưới mức tối thiểu yêu cầu. Để đảm bảo có thể mua ở mọi nơi, vui lòng cập nhật giá của gói này để ít nhất bằng giá tối thiểu của Steam.`,
  pC = `Bạn có 1 thay đổi chưa được lưu. Hủy thay đổi sẽ xóa thông tin giảm giá mới và đưa giảm giá đã cập nhật về thiết lập trước đó.`,
