  wO = `Thiết kế: Ảnh biểu ngữ tiêu điểm sẽ tự động có một mục hiện tại chân ảnh với dòng chữ mô tả loại hình quảng bá (vd: 'Ưu đãi cuối tuần') và ngày kết thúc khuyến mãi.`,
