  MO = `Để rõ ràng, các cụm từ như "Ưu đãi loạt sản phẩm", "Ưu đãi từ nhà phát hành", "Cuối tuần miễn phí" không nên được đưa vào`,
  NO = `Dành không gian phần trên của ảnh cho vị trí 'ảnh biểu ngữ tiêu điểm' để được phủ lên trên ảnh biểu trưng.`,
