  QO = `Yêu cầu hai định dạng, phiên bản lớn và di động. Với bản xem trước, bạn sẽ chỉ tải lên ảnh tĩnh của ảnh takeover, kể cả khi bạn cũng đang tạo ra phiên bản động.`,
