  _k = `Cách dùng: hình ảnh này được sử dụng để đại diện sự kiện của bạn trong trung tâm tin tức Steam, trên trang ưu đãi đặc biệt, và sẽ xuất hiện dưới dạng bản xem trước khi mọi người chia sẻ URL sự kiện trên mạng xã hội`,
