  jk = `Gửi tư liệu`,
  Mk = `Gửi tư liệu...`,
  Nk = `Bạn đã gửi tư liệu lên Valve và hoàn thành nghĩa vụ! Tư liệu được gửi sẽ tự động xuất hiện trên trang tổng quan của đội ngũ Steam để xem xét và chuẩn bị cho đợt quảng bá.`,
  Pk = `Tư liệu đã được gửi!`,
  Fk = `Đã gửi tư liệu! Không cần thực hiện thêm hành động liên quan tới tư liệu.`,
  Ik = `Nhấp dưới đây để gửi tư liệu quảng bá cho Valve. Khi đã gửi, đội ngũ Steam sẽ bắt đầu xem xét và chuẩn bị tài liệu để giới thiệu.`,
  Lk = `Không thể gửi, URL bên trên không hợp lệ`,
  Rk = `Vui lòng điền những ô bắt buộc để có thể gửi yêu cầu tư liệu.`,
  zk = `Ưu đãi kết thúc vào %1$s`,
  Bk = `Quan trọng! Yêu cầu về tư liệu`,
  Vk = `Vui lòng xem lại chặng mục bên dưới và gửi tư liệu cần thiết để chúng tôi có thể biên dịch ưu đãi này sang tất cả ngôn ngữ được Steam hỗ trợ!`,
  Hk = `Mỗi tư liệu phải dưới 5MB`,
  Uk = `Tranh ảnh phải nằm trong file Photoshop (PSD) theo lớp`,
  Wk = `Tranh ảnh trò chơi/nhân vật chính ở độ phân giải cao nhất có thể (ưu tiên Smart Object). Làm thế sẽ cho phép chúng tôi sử dụng lại tư liệu để tạo các tác phẩm quảng bá Steam khi cần.`,
  Gk = `Logo (ưu tiên Smart Object) tách biệt với tranh ảnh.`,
  Kk = `Tất cả nội dung bằng chữ nên chỉnh sửa được, đặt trong thư mục "text" riêng trong tài liệu PSD, nhằm giúp việc bản địa hóa dễ dàng hơn.`,
  qk = `Bao gồm tất cả font chữ sử dụng (đặc biệt các font tùy chỉnh).`,
  Jk = `Vui lòng giữ tất cả thiết kế kiểu chữ và phân lớp trong Photoshop. Đừng liên kết tới file từ những chương trình khác như Illustrator.`,
  Yk = `Đối với tư liệu ảnh động, vui lòng cung cấp một đoạn vòng lặp liền mạch ở định dạng MP4 hoặc PNG không kèm chữ và logo. Hãy đảm bảo văn bản là một lớp riêng và không phải ảnh động để đội ngũ của chúng tôi có thể dễ dàng bản địa hóa.`,
  Xk = `Để tìm hiểu thêm và xem ví dụ, cũng như chi tiết về tư liệu ảnh động, vui lòng xem <1>Tư liệu hình ảnh khuyến mãi cho cửa hàng</1>`,
  Zk = `Tin nhắn từ đại diện Steam`,
  Qk = `Chặng mục tư liệu`,
  $k = `Tải lên ảnh biểu trưng tiêu điểm (dọc) xem trước`,
  eA = `Sử dụng trình tải lên bên dưới để gửi bản xem trước và để đảm bảo hình ảnh tuân thủ kích thước và cách cắt theo mẫu.`,
  tA = `Không cần tư liệu thông điệp marketing`,
  nA = `Thông điệp marketing sẽ sử dụng ảnh biểu trưng chính, ảnh chụp và trailer có sẵn đang hiển thị trên trang cửa hàng của trò chơi.`,
  rA = `Xem trước thông điệp marketing tải lên`,
  iA = `Tải lên bản xem trước tư liệu khuyến mãi của ứng dụng`,
  aA = `Sử dụng công cụ tải lên bên dưới để gửi bản xem trước và đảm bảo hình ảnh tuân thủ kích thước và cách cắt theo mẫu.`,
  oA = `Tải lên bản xem trước cho ảnh takeover`,
  sA = `Sử dụng công cụ tải lên bên dưới để gửi bản xem trước cho ảnh takeover và takeover di động nhằm đảm bảo hình ảnh của bạn tuân thủ kích thước và cách cắt theo mẫu.`,
  cA = `Tải lên bản xem trước cho ảnh biểu ngữ takeunder`,
  lA = `Sử dụng công cụ tải lên bên dưới để gửi bản xem trước cho ảnh takeunder và takeunder di động nhằm đảm bảo hình ảnh của bạn tuân thủ kích thước và cách cắt theo mẫu.`,
  uA = `Tải lên bản xem trước cho ảnh thuộc trang ưu đãi`,
  dA = `Sử dụng công cụ tải lên bên dưới để gửi bản xem trước cho năm mục liên quan đến trang ưu đãi để bản địa hóa. Đảm bảo hình ảnh của bạn tuân thủ kích thước và cách cắt theo mẫu.`,
  fA = `Hướng dẫn đặc biệt`,
  pA = `Nhập bất kỳ chỉ dẫn đặc biệt hoặc thông tin bổ sung nào mà đại diện Steam nên biết về tư liệu của bạn. Ví dụ, bạn có bao gồm thông tin về một bản cập nhật tương ứng không? Có hướng dẫn cụ thể để sử dụng các yếu tố thương hiệu không?`,
  mA = `mọi điều đặc biệt cần biết về tư liệu của bạn`,
  hA = `Thông tin liên lạc`,
  gA = `Nhập một hoặc nhiều địa chỉ email của người mà chúng tôi nên liên hệ nếu có thắc mắc hay phản hồi liên quan đến tư liệu đã tải lên.`,
  _A = `Danh sách email phân cách bằng dấu phẩy`,
  vA = `Hoàn tất gửi tư liệu!`,
  yA = `Tiếp theo, nhóm quảng bá Steam sẽ xem xét tư liệu và chuẩn bị tài liệu cho chương trình khuyến mãi của bạn. Chúng tôi sẽ liên lạc nếu cần thêm thông tin`,
  bA = `Các bước tiếp theo:`,
  xA = `Bạn muốn xem lại những gì đã gửi?`,
  SA = `Xem chi tiết tư liệu đã gửi`,
  CA = `Đừng quên nhập giảm giá`,
  wA = `Mở công cụ giảm giá`,
  TA = `Sớm nhất có thể`,
  EA = `Thông báo bản cập nhật lớn`,
  DA = `Chúng ta cần tạo sự kiện mới thuộc loại cập nhật lớn, gắn nhãn chỉ định sử dụng trong thông điệp marketing này. <1>Vui lòng cũng xem danh sách yêu cầu</1>`,
  OA = `Tạo thông báo mới`,
  kA = `Thông báo cập nhật cho thông điệp marketing có thể <1>chỉnh sửa tại đây</1>.`,
  AA = `Thỏa thuận này đã được xem xét và ký bởi:`,
  jA = `Xem xét luật lệ`,
  MA = `Tư liệu khuyến mãi của ứng dụng (%1$s)`,
  NA = `Tạo thông báo cập nhật lớn cho thông điệp marketing`,
  PA = `Vui lòng xem xét và chấp nhận những yêu cầu sau đây:`,
  FA = `Mô tả sự kiện phải được trình bày kỹ càng để giải thích bản cập nhật — lý do, thay đổi chính, tính năng mới, ghi chú cập nhật, v.v.`,
  IA = `Tiêu đề của sự kiện phải hấp dẫn, hào hứng, và dễ hiểu cho cả người dùng đã có thời gian ngừng chơi.`,
  LA = `Key art nên thể hiện rõ bản cập nhật và không chứa thêm nội dung chữ hoặc sao chép.`,
  RA = `Nhấp vào đây để chấp nhận luật lệ`,
  zA = `Màu nền`,
  BA = `Sửa màu tổng thể của hình nền`,
  VA = `Hình nền dạng lát gạch`,
  HA = `Một ảnh lớn, không phải lưới ô vuông, kích thước cố định (mặc định)`,
  UA = `Lặp hình nền theo chiều ngang`,
  WA = `Lặp hình nền theo chiều dọc`,
  GA = `Lặp hình nền trên mọi chiều`,
  KA = `Một ảnh, bao phủ và làm mờ`,
  qA = `Màu mũi tên khung xoay tua`,
  JA = `Nếu màu nền hoặc hình nền có màu rất sáng, sẽ khó nhìn thấy mũi tên. Sử dụng thiết lập này để ghi đè màu trắng mặc định của mũi tên khung xoay tua.`,
  YA = `Nếu màu nền hoặc hình nền có màu rất sáng, sẽ khó nhìn thấy mũi tên. Sử dụng thiết lập này để ghi đè màu trắng và xám mặc định của breadcrumb khung xoay tua. Sẽ áp dụng chủ yếu cho màn hình nhỏ hơn như Steam Deck.`,
  XA = `Màu khung xoay tua`,
  ZA = `Kiểu mũi tên khung xoay tua`,
  QA = `Mũi tên đơn`,
  $A = `Mũi tên đôi`,
