  _I = `Nhắc nhở thông điệp marketing - %1$s`,
  vI = `Xem trước thông điệp marketing: `,
  yI = `Yêu cầu mã playtest`,
  bI = `Sử dụng mẫu này để yêu cầu mã Steam cho gói Playtest của bạn. Tất cả yêu cầu mã Steam đều được Valve xem xét theo từng trường hợp cụ thể, thường trong vòng 48-72 giờ.`,
  xI = `Vui lòng dùng ô bên dưới để cho biết về dự định sử dụng các mã này và chúng tôi có thể giúp đảm bảo bạn đang yêu cầu đúng số lượng mã cho nhu cầu.`,
