  yV = `Màu sắc`,
  bV = `nhập mã định danh độc nhất...`,
  xV = `Dùng bởi lệnh gọi API (tối đa %1$s ký tự). Bắt buộc chữ và số viết thường. Dài ít nhất 3 ký tự. Có hỗ trợ thêm dấu '_' và '-'. Không cho phép khoảng trống/phím cách.`,
  SV = `Mã định danh chứa các ký tự không được hỗ trợ. Bắt buộc chữ và số viết thường. Dài ít nhất 3 ký tự. Có hỗ trợ thêm dấu '_' và '-'. Không cho phép khoảng trống/phím cách.`,
  CV = `Mã định danh không thể bắt đầu bằng từ 'steam_' vốn để dành cho các biểu tượng chính thức.`,
  wV = `Với mỗi biểu tượng, tải lên file .png hoặc .svg và đặt một mã định danh độc nhất sẽ được dùng bởi lệnh gọi API.`,
  TV = `Biểu tượng (File .SVG hoặc .PNG)`,
  EV = `Biểu tượng SVG sẽ hiển thị theo viewbox 36px x 36px. Vui lòng tạo tư liệu phù hợp. File PNG phải là tư liệu hình vuông với chiều rộng/cao từ 24px đến 256px.`,
  DV = `Biểu tượng SVG sẽ hiển thị theo viewbox 36px x 36px. Vui lòng tạo tư liệu phù hợp. File PNG phải là tư liệu hình vuông với chiều rộng/cao từ 24px đến 256px.`,
  OV = `Biểu tượng SVG này có viewbox hoặc chiều cao/rộng bằng %1$s và kết quả hiển thị có thể không đúng.`,
