  fU = `Do các thành tựu có thể xuất hiện ở bất kỳ đâu trong cộng đồng Steam, tên và biểu tượng bạn đặt phải phù hợp cho mọi lứa tuổi và đối tượng. Valve hoàn toàn có thể xóa trò chơi khỏi cửa hàng nếu thành tựu vi phạm <1>Hướng dẫn về nội dung & cộng đồng</1> hoặc có tính phản cảm.`,
  pU = `Để kích hoạt đầy đủ thành tựu, và hoàn thành chặng mục phát hành, bạn cần đánh dấu vào ô tương ứng trong phần thông tin trang cửa hàng bên dưới mục <1>'Tính năng hỗ trợ'</1>.`,
